import assert from "node:assert/strict";
import type {GeneratedBody} from "../../src/core/generators/definition";
import {legacy2018AutumnSystemsKnowledgeFacts as facts} from "./legacy-2018-autumn-systems-knowledge-review";
const compilerStages=new Map([["字句解析",0],["構文解析",1],["意味解析",2],["型検査",2],["中間コード生成",3],["最適化",4],["目的コード生成",5]]);
const secondary=new Map([["アルカリマンガン乾電池",false],["マンガン乾電池",false],["酸化銀電池",false],["空気亜鉛電池",false],["燃料電池",false],["リチウムイオン電池",true]]);
/** Independent finite countermodel: lock bit sets are literal protected rows,
 * with identical exclusive mode. No production simulator/range is imported. */
export function legacy2018AutumnLockCountermodel(){let distinctRowsCanRun=0,coarseAddsConflict=0;for(let left=1;left<256;left++)for(let right=1;right<256;right++){const fineConflict=(left&right)!==0,coarseConflict=(255&255)!==0;if(fineConflict)assert(coarseConflict);else{distinctRowsCanRun++;assert(coarseConflict);coarseAddsConflict++;}}assert.equal(distinctRowsCanRun,6050);assert.equal(coarseAddsConflict,6050);return{finePairChecks:255*255,distinctRowsCanRun,coarseAddsConflict,rowLocksFor100Rows:100,tableLocksFor100Rows:1};}
/** All subsets of2–8 distinct rows and1–3 identical work units. Only lock
 * waiting can block progress; arrivals/work/lock release are held fixed. */
export function legacy2018AutumnDistinctRowSchedules(){let schedules=0;for(let mask=1;mask<256;mask++){const count=mask.toString(2).split("").filter(x=>x==="1").length;if(count<2)continue;for(let work=1;work<=3;work++){const rowCompletions=Array(count).fill(work) as number[],tableCompletions=Array.from({length:count},(_,i)=>(i+1)*work),rowWait=0,tableWait=tableCompletions.reduce((sum,t)=>sum+t-work,0);assert.equal(Math.max(...rowCompletions),work);assert.equal(Math.max(...tableCompletions),count*work);assert(tableWait>rowWait);assert(count*(count*work)>count*work,"same count / smaller elapsed has greater throughput");schedules++;}}assert.equal(schedules,741);return{schedules,distinctRows:[2,8],identicalWorkUnits:[1,3],rowWait:0,tableWaitStrictlyGreater:true};}
export function legacy2018AutumnSystemsKnowledgeOracle(source:string,b:GeneratedBody,v:number[]){const f=facts.find(f=>source===`2018h30a-fe-am-${f.number}`);assert(f);assert.equal(v.length,f.variedIndices.length);assert(v.every(n=>n===0||n===1));assert.deepEqual(b.prompt.map(p=>{assert(p.type==="paragraph");return p.text;}),f.prompt);assert.equal(b.choices.length,4);const actual=b.choices.map(bs=>{assert.equal(bs.length,1);assert(bs[0].type==="paragraph");return bs[0].text;}),expected=f.original.map((text,i)=>{const at=f.variedIndices.indexOf(i);return at>=0&&v[at]===1?f.changed[at]:text;});assert.deepEqual(actual,expected);assert.equal(new Set(actual).size,4);const reviewed=new Map<string,boolean>([...f.original.map((s,i)=>[s,i===f.correct] as const),...f.changed.map(s=>[s,false] as const)]);const truth=actual.map(text=>{assert(reviewed.has(text));return reviewed.get(text)!;});
 if(f.number===19){const stages=actual.map(s=>{assert(compilerStages.has(s));return compilerStages.get(s)!;});assert.deepEqual(truth,stages.map(n=>n===Math.min(...stages)));}
 if(f.number===23)assert.deepEqual(truth,actual.map(s=>{assert(secondary.has(s));return secondary.get(s)!;}));
 if(f.number===27){const rangeA=Array.from({length:101},(_,i)=>i),rangeB=Array.from({length:1001},(_,i)=>i);assert.equal(typeof rangeA[0],typeof rangeB[0]);assert(rangeB.some(v=>!rangeA.includes(v)));assert.equal(truth[1],true);}
 assert.equal(truth.filter(Boolean).length,1);assert.equal(b.correctIndex,truth.indexOf(true));for(const term of f.explanation)assert(b.explanation.includes(term),`${source}:${term}`);assert(!/原資料では[アイウエ]が|[アイウエ]が正答/.test(b.explanation));return truth;
}
